AssistantMessageToolRequest(name='create', tool_call_id='tooluse_ZuWYbL8BE5OXBs9rrtU5bg', arguments={'file_text': '/* Global styles */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  color-scheme: dark;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
  color: #e0e0e0;
  line-height: 1.6;
  min-height: 100vh;
  padding: 20px;
}

main {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
}

.container {
  width: 100%;
  max-width: 700px;
  background: rgba(22, 33, 62, 0.95);
  border: 1px solid rgba(100, 150, 255, 0.3);
  border-radius: 12px;
  padding: 40px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
}

h1 {
  font-size: 28px;
  margin-bottom: 12px;
  color: #6496ff;
  font-weight: 600;
}

.intro {
  color: #b0b0b0;
  margin-bottom: 32px;
  font-size: 15px;
}

/* Form styling */
form {
  display: flex;
  flex-direction: column;
  gap: 28px;
}

.form-field {
  display: flex;
  flex-direction: column;
}

fieldset {
  border: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

legend {
  font-size: 16px;
  font-weight: 600;
  color: #e0e0e0;
  padding: 0;
  margin-bottom: 4px;
  cursor: default;
}

legend span[aria-hidden="true"] {
  color: #ff6b6b;
  margin-left: 4px;
}

.help-text {
  font-size: 13px;
  color: #8899cc;
  margin-top: 4px;
  font-style: italic;
}

/* Checkbox styling */
.checkbox-group {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 0;
}

input[type="checkbox"] {
  width: 20px;
  height: 20px;
  margin: 0;
  cursor: pointer;
  accent-color: #6496ff;
  flex-shrink: 0;
}

input[type="checkbox"]:focus {
  outline: 2px solid #6496ff;
  outline-offset: 2px;
  border-radius: 2px;
}

input[type="checkbox"]:checked {
  background-color: #6496ff;
}

label {
  font-size: 15px;
  color: #d0d0d0;
  cursor: pointer;
  user-select: none;
  display: flex;
  align-items: center;
}

label:hover {
  color: #e8e8e8;
}

/* Error message styling */
#q1-error,
#q2-error,
#q3-error {
  color: #ff6b6b;
  font-size: 13px;
  margin-top: 8px;
  padding: 8px 12px;
  background: rgba(255, 107, 107, 0.1);
  border-left: 3px solid #ff6b6b;
  border-radius: 4px;
}

/* Submit button */
.submit-button {
  align-self: flex-start;
  padding: 12px 32px;
  font-size: 15px;
  font-weight: 600;
  color: #fff;
  background: linear-gradient(135deg, #6496ff 0%, #4a7cff 100%);
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.3s ease;
  margin-top: 16px;
}

.submit-button:hover:not(:disabled) {
  background: linear-gradient(135deg, #7da3ff 0%, #5a8cff 100%);
  box-shadow: 0 8px 20px rgba(100, 150, 255, 0.4);
  transform: translateY(-2px);
}

.submit-button:focus {
  outline: 2px solid #6496ff;
  outline-offset: 2px;
}

.submit-button:active:not(:disabled) {
  transform: translateY(0);
}

.submit-button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

/* Results section */
.results {
  margin-top: 32px;
  padding: 20px;
  background: rgba(100, 150, 255, 0.1);
  border: 1px solid rgba(100, 150, 255, 0.5);
  border-radius: 8px;
}

.results h2 {
  font-size: 20px;
  color: #6496ff;
  margin-bottom: 12px;
}

.results p {
  color: #d0d0d0;
  font-size: 15px;
  line-height: 1.6;
}

/* Responsive design */
@media (max-width: 600px) {
  .container {
    padding: 28px 20px;
  }

  h1 {
    font-size: 24px;
  }

  .submit-button {
    width: 100%;
    align-self: stretch;
  }
}

/* High contrast / Forced Colors support */
@media (prefers-contrast: more) {
  legend span[aria-hidden="true"] {
    font-weight: bold;
  }

  input[type="checkbox"]:focus {
    outline-width: 3px;
  }
}

/* Reduced motion support */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* Forced Colors mode (Windows High Contrast) */
@media (forced-colors: active) {
  .container {
    border-color: CanvasText;
  }

  input[type="checkbox"] {
    border: 1px solid CanvasText;
  }

  input[type="checkbox"]:focus {
    outline: 2px solid CanvasText;
  }

  .submit-button {
    background: ButtonFace;
    color: ButtonText;
    border: 1px solid ButtonText;
  }

  .submit-button:hover {
    background: Highlight;
    color: HighlightText;
  }
}
