const fs = require('fs');
const path = require('path');

async function runAccessibilityTest() {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  const htmlPath = path.join(__dirname, 'index.html');
  const htmlContent = fs.readFileSync(htmlPath, 'utf-8');

  // Load HTML with file:// protocol
  await page.goto(`file://${htmlPath}`, { waitUntil: 'load' });

  // Inject axe-core from node_modules
  const axePath = require.resolve('axe-core');
  await page.addScriptTag({ path: axePath });

  // Run axe
  const results = await page.evaluate(() => {
    return new Promise((resolve) => {
      window.axe.run((error, results) => {
        resolve(results);
      });
    });
  });

  await browser.close();

  // Separate WCAG violations from best-practice
  const wcagViolations = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bestPracticeViolations = results.violations.filter(v => v.tags.includes('best-practice'));

  // Output results
  console.log('=== ACCESSIBILITY TEST RESULTS ===\n');

  if (wcagViolations.length === 0 && bestPracticeViolations.length === 0) {
    console.log('✓ PASS: No accessibility violations found\n');
    process.exit(0);
  }

  if (wcagViolations.length > 0) {
    console.log('WCAG VIOLATIONS (must fix):');
    wcagViolations.forEach(v => {
      console.log(`\n  ${v.id} [${v.impact.toUpperCase()}]`);
      console.log(`  ${v.description}`);
      console.log(`  Targets: ${v.nodes.map(n => n.target.join(' > ')).join(' | ')}`);
